554:   if (!value || value.schemaVersion !== 1 || typeof value.contextId !== 'string' || !value.contextId
555:     || !value.snapshots || !value.diagramRevisions || !Array.isArray(value.past) || !Array.isArray(value.future)) throw new Error('Invalid canvas history');
556:   for (const key of [value.headId, value.baselineId, ...value.past, ...value.future]) {
557:     if (typeof key !== 'string' || !Object.hasOwn(value.snapshots, key)) throw new Error('Unknown canvas history reference');
558:   }
559:   validateCanvasViews(value.canvasViews, value.snapshots);
560:   for (const [key, revision] of (changed ? changed.revisions.map(key => [key, value.diagramRevisions[key]] as const) : Object.entries(value.diagramRevisions))) {
561:     if (revision.diagram.revisionId !== key || revision.id !== key || revision.diagramId !== revision.diagram.diagramId || !revision.nodeRefs) throw new Error('Invalid diagram history identity');
562:     validateDiagram(revision.diagram);
563:     validated.add(revision.diagram);
564:     if (revision.parentId && (value.diagramRevisions[revision.parentId]?.diagramId ?? value.revisionBoundary?.[revision.parentId]) !== revision.diagramId) throw new Error('Invalid diagram revision parent');
565:     const refs = diagramContentNodes(revision.diagram.content).map(n => revision.nodeRefs[n.id]);
566:     if (refs.some(ref => typeof ref !== 'string' || !ref) || new Set(refs).size !== refs.length) throw new Error('Invalid logical node identities');
567:   }
568:   for (const [key, snapshot] of (changed ? changed.snapshots.map(key => [key, value.snapshots[key]] as const) : Object.entries(value.snapshots))) {
569:     if (snapshot.id !== key || !snapshot.document || !snapshot.view || !snapshot.nodeOrigins || !snapshot.diagramBindings
570:       || snapshot.parentId && !Object.hasOwn(value.snapshots, snapshot.parentId)) throw new Error('Invalid canvas checkpoint');
571:     if ('contents' in snapshot.document.scene) throw new Error('Canvas checkpoint must not embed diagrams');
572:     const contents: Record<string, Diagram> = {};
573:     for (const [diagramId, revisionId] of Object.entries(snapshot.diagramBindings)) {
574:       const revision = Object.hasOwn(value.diagramRevisions, revisionId) && value.diagramRevisions[revisionId];
575:       if (!revision || revision.diagram.id !== diagramId) throw new Error('Invalid diagram binding');
576:       contents[diagramId] = revision.diagram;
577:     }
