579:     if (snapshot.document.alternatives) validateDiagramAlternatives(snapshot.document.alternatives, id => value.diagramRevisions[id]);
580:     validateRevisionSelections(migrateRevisionSelections(snapshot.document), id => value.diagramRevisions[id]);
581:     for (const [id, variant] of Object.entries(migrateRevisionSelections(snapshot.document).revisionReviews ?? {})) {
582:       if (id !== variant.id) throw Error('Invalid variant identity');
583:       validateRevisionReview(variant, id => value.diagramRevisions[id]);
584:     }
585:     const scene = { root: snapshot.document.scene.root, contents };
586:     for (const [diagramId, context] of Object.entries(snapshot.document.diagramContexts ?? {})) {
587:       if (diagramId !== context.diagramId || !Object.values(contents).some(diagram => diagram.diagramId === diagramId))
588:         throw Error('Diagram agent context has no owning diagram');
589:       validateDiagramAgentContext(context);
590:     }
591:     validateCanvasScene(scene, validated);
592:     if (snapshot.transactionId !== undefined && (typeof snapshot.transactionId !== 'string' || !snapshot.transactionId)) throw Error('Invalid transaction reference');
593:     if (snapshot.document.jumps) validateCanvasJumps(scene, snapshot.document.jumps);
594:     validateConnections(scene, documentFromHistory(value, key).edges);
595:   }
