599: export function documentFromHistory(record: CanvasHistoryRecord, snapshotId = record.headId): ResolvedCanvasDocument {
600:   const snapshot = record.snapshots[snapshotId];
601:   if (!snapshot) throw new Error('Unknown canvas checkpoint');
602:   const contents = Object.fromEntries(Object.entries(snapshot.diagramBindings).map(([diagramId, revisionId]) => [diagramId, record.diagramRevisions[revisionId].diagram]));
603:   const scene = { root: snapshot.document.scene.root, contents };
604:   const decode = (anchor: CanvasConnection['target'], key: string): DiagramAnchor => {
605:     if (anchor.kind === 'box') return anchor;
606:     if (snapshot.unresolvedAnchors?.[key]) return snapshot.unresolvedAnchors[key];
607:     const box = findOwner(scene.root, anchor.displayNodeId);
608:     const revision = box?.kind === 'diagram' && record.diagramRevisions[snapshot.diagramBindings[box.contentId]];
609:     const contentNodeId = revision && Object.entries(revision.nodeRefs).find(([, ref]) => ref === anchor.contentNodeId)?.[0];
610:     if (!revision || !contentNodeId) throw new Error('Unresolvable canonical anchor');
611:     return { ...anchor, contentNodeId, revisionId: revision.diagram.content.revisionId };
612:   };
613:   const result = structuredClone({ ...migrateDiagramAlternatives(snapshot.document, id => record.diagramRevisions[id], snapshot.diagramBindings), scene, edges: snapshot.document.edges.map(edge => ({ ...edge,
614:     source: decode(edge.source, edge.id + ':source') as ContentNodeAnchor, target: decode(edge.target, edge.id + ':target') })) });
615:   Object.values(result.scene.contents).forEach(deepFreeze);
616:   return result;
617: }
