43: export class DefaultCanvasHistoryService implements CanvasHistoryService {
44:   canvasViewComparison(context: CanvasEditingContext, viewId: string) { return this.history(context).canvasViewComparison(viewId); }
45:   startGeneration(context: CanvasEditingContext, parentId: string, candidates: { id: string; name: string; generation: import('./canvasGeneration').CanvasGeneration }[], pinned?: CanvasHistoryRecord) { return this.history(context).startGeneration(parentId, candidates, pinned); }
46:   updateGeneration(context: CanvasEditingContext, viewId: string, generation: import('./canvasGeneration').CanvasGeneration, proposed?: CanvasHistoryRecord) { this.history(context).updateGeneration(viewId, generation, proposed); }
47:   canvasViews(context: CanvasEditingContext) { return this.history(context).canvasViews(); }
48:   canvasView(context: CanvasEditingContext, input: import('./canvasView').CanvasViewCommand, view?: unknown) { return this.history(context).canvasView(input, view); }
49:   constructor(private readonly validation: import('./canvasHistory').HistoryValidation = 'all') {}
50:   // Object handles isolate two viewers of the same persisted context, and allow GC on close.
51:   private readonly contexts = new WeakMap<CanvasEditingContext, CanvasHistory>();
52: 
53:   openContext(document: ResolvedCanvasDocument, view: unknown, record?: CanvasHistoryRecord): CanvasEditingContext {
54:     const history = new CanvasHistory(document, view, record, this.validation);
55:     const context = Object.freeze({ contextId: history.contextId });
56:     this.contexts.set(context, history);
57:     return context;
58:   }
59:   private history(context: CanvasEditingContext) {
60:     const history = this.contexts.get(context);
61:     if (!history) throw new Error('Unknown diagram editing context');
62:     return history;
63:   }
64:   state(context: CanvasEditingContext): CanvasContextState {
65:     const history = this.history(context), head = history.head;
66:     return { checkpointId: head.id, document: head.document, view: head.view, canUndo: history.canUndo, canRedo: history.canRedo };
67:   }
68:   resolve(context: CanvasEditingContext, diagramId: string) {
69:     const history = this.history(context);
70:     return history.diagrams.resolve(history.contextId, diagramId);
71:   }
72:   document(context: CanvasEditingContext) { return this.history(context).document(); }
73:   append(context: CanvasEditingContext, document: ResolvedCanvasDocument, view: unknown, correspondence?: ReadonlyMap<string, string>) {
74:     this.history(context).append(document, view, correspondence);
75:   }
76:   navigate(context: CanvasEditingContext, redo = false) {
77:     const linked = this.history(context).navigationTransactionId(redo);
78:     if (linked) throw Error('Use workspace undo/redo for a canvas transfer.');
79:     return !!this.history(context).navigate(redo);
80:   }
81:   prepareTransfer(context: CanvasEditingContext, input: TransferInput, destination?: CanvasEditingContext) {
82:     return prepareCanvasTransfer(this.history(context).export(), input, destination ? this.history(destination).export() : undefined);
83:   }
84:   transferBoundary(context: CanvasEditingContext, transaction: CanvasTransfer, canvasId: string, redo = false) {
85:     return transferBoundary({ headId: this.history(context).headId }, transaction, canvasId, redo);
86:   }
87:   prepareTransferNavigation(source: CanvasEditingContext, destination: CanvasEditingContext, transaction: CanvasTransfer, redo = false) {
88:     return prepareTransferNavigation(this.history(source).export(), this.history(destination).export(), transaction, redo);
89:   }
90:   reset(context: CanvasEditingContext) { this.history(context).reset(); }
91:   persistenceChanges(context: CanvasEditingContext, since?: number) { return this.history(context).persistenceChanges(since); }
92:   retireTransactions(context: CanvasEditingContext, ids: ReadonlySet<string>) { this.history(context).retireTransactions(ids); }
93:   exportContext(context: CanvasEditingContext, currentOnly = false) { return this.history(context).export(currentOnly); }
94:   navigation(context: CanvasEditingContext) { return this.history(context).navigation(); }
95:   forkContext(context: CanvasEditingContext, view: unknown) { return this.history(context).fork(view); }
96:   adopt(context: CanvasEditingContext, proposed: CanvasHistoryRecord) { this.history(context).adopt(proposed); }
97: }

