6: const id = z.string().min(1).max(500).refine(value => !['__proto__', 'constructor', 'prototype'].includes(value));
7: const offset = z.number().min(0).max(1).optional();
8: const side = z.enum(['auto', 'horizontal', 'left', 'right', 'top', 'bottom']).default('auto');
9: export const contentNodeAnchorSchema = z.object({
10:   kind: z.literal('content-node'), displayNodeId: id, contentNodeId: id, revisionId: id, side, offset
11: }).strict();
12: export const boxAnchorSchema = z.object({ kind: z.literal('box'), displayNodeId: id, side, offset }).strict();
13: export const anchorSchema = z.discriminatedUnion('kind', [contentNodeAnchorSchema, boxAnchorSchema]);
14: export const arrowLabelSchema = z.object({
15:   text: z.string().max(120),
16:   /** Absolute canvas pixels: horizontal center and text baseline, before pan/zoom. */
17:   position: z.object({ x: z.number().finite(), y: z.number().finite() }).strict().optional()
18: }).strict();
19: export const arrowAppearanceSchema = z.object({
20:   color: z.string().regex(/^#[0-9a-fA-F]{6}$/).default('#88c0d0'),
21:   lineStyle: z.enum(['solid', 'dashed']).default('solid'),
22:   label: z.union([z.string().max(120), arrowLabelSchema]).default('')
23: }).strict();
24: export const diagramConnectionSchema = z.object({
25:   id, source: contentNodeAnchorSchema, target: anchorSchema,
26:   appearance: arrowAppearanceSchema
27: }).strict();
28: export type ContentNodeAnchor = z.infer<typeof contentNodeAnchorSchema>;
29: export type GridBoxAnchor = z.infer<typeof boxAnchorSchema>;
30: export type DiagramAnchor = ContentNodeAnchor | GridBoxAnchor;
31: export type DiagramConnection = z.infer<typeof diagramConnectionSchema>;
32: export type ArrowAppearance = DiagramConnection['appearance'];
33: export type ArrowLabel = z.infer<typeof arrowLabelSchema>;
34: export const defaultArrowAppearance: ArrowAppearance = { color: '#88c0d0', lineStyle: 'solid', label: '' };
