36: /** Legacy saved edges and callers may still supply a plain string. */
37: export function getArrowLabel(appearance: ArrowAppearance): ArrowLabel {
38:   return typeof appearance.label === 'string' ? { text: appearance.label } : appearance.label;
39: }
