41: export function connectionBox(scene: LineGridScene, displayNodeId: string): GridBox | undefined {
42:   if (!displayNodeId.startsWith('grid:')) return undefined;
43:   const find = (box: GridBox): GridBox | undefined => box.id === displayNodeId.slice(5) ? box
44:     : box.kind === 'container' ? box.children.map(find).find(Boolean) : undefined;
45:   return find(scene.root);
46: }
47: 
48: export function validateConnectionAnchor(scene: LineGridScene, anchor: DiagramAnchor, allowStale = false) {
49:   const box = connectionBox(scene, anchor.displayNodeId);
50:   if (!box) throw new Error('Connection requires an existing GridBox');
51:   if (anchor.kind === 'box') return;
52:   if (box.kind !== 'diagram') throw new Error('Content anchor requires a diagram');
53:   const content = scene.contents[box.contentId].content;
54:   if (allowStale && content.revisionId !== anchor.revisionId) return;
55:   if (content.revisionId !== anchor.revisionId || !connectionContentNodes(content).some(node => node.id === anchor.contentNodeId)) {
56:     throw new Error('STALE_CONTENT_NODE: choose a current connection endpoint');
57:   }
58: }
59: 
60: export function validateConnections(scene: LineGridScene, input: unknown): DiagramConnection[] {
61:   const edges = z.array(diagramConnectionSchema).max(2000).parse(input ?? []);
62:   const seen = new Set<string>();
63:   for (const edge of edges) {
64:     if (seen.has(edge.id)) throw new Error('Duplicate connection ID');
65:     seen.add(edge.id);
66:     validateConnectionAnchor(scene, edge.source, true);
67:     validateConnectionAnchor(scene, edge.target, true);
68:   }
69:   return edges;
70: }
71: 
72: /** Deletions remove incident edges. Only proven node correspondence can rebase changed content. */
73: export function reconcileConnections(before: LineGridScene, after: LineGridScene, edges: readonly DiagramConnection[], nodeIds?: ReadonlyMap<string, string>): DiagramConnection[] {
74:   const update = <T extends DiagramAnchor>(anchor: T): T => {
75:     if (anchor.kind !== 'content-node') return anchor;
76:     const oldBox = connectionBox(before, anchor.displayNodeId), newBox = connectionBox(after, anchor.displayNodeId);
77:     if (oldBox?.kind !== 'diagram' || newBox?.kind !== 'diagram') return anchor;
78:     const oldContent = before.contents[oldBox.contentId].content, content = after.contents[newBox.contentId].content;
79:     if (oldContent.revisionId === content.revisionId || oldContent.revisionId !== anchor.revisionId) return anchor;
80:     const mapped = nodeIds?.get(anchor.contentNodeId);
81:     if (mapped && connectionContentNodes(content).some(node => node.id === mapped))
82:       return { ...anchor, revisionId: content.revisionId, contentNodeId: mapped };
83:     if (oldContent.ascii !== content.ascii || oldContent.structure.kind !== content.structure.kind) return anchor;
84:     const oldNode = connectionContentNodes(oldContent).find(node => node.id === anchor.contentNodeId);
85:     const node = oldNode && connectionContentNodes(content).find(node => node.line === oldNode.line && node.startColumn === oldNode.startColumn);
86:     return node ? { ...anchor, revisionId: content.revisionId, contentNodeId: node.id } : anchor;
87:   };
88:   return edges.filter(edge => connectionBox(after, edge.source.displayNodeId) && connectionBox(after, edge.target.displayNodeId))
89:     .map(edge => ({ ...edge, source: update(edge.source), target: update(edge.target) }));
90: }

