1: import type { DiagramElementMapping } from "../records/domain";
2: 
3: /** Grid coordinates are zero-based cells; right and bottom edges are exclusive. */
4: export interface GridPoint { column: number; row: number }
5: export interface GridSize { columns: number; rows: number }
6: export interface GridBounds extends GridPoint, GridSize {}
7: 
8: export type { Diagram } from './diagram';
9: import type { Diagram } from './diagram';
10: 
11: export type GridBox = {
12:   id: string;
13:   position: GridPoint;
14:   minimumSize?: GridSize;
15:   collapsed: boolean;
16:   collapsedContentId?: string;
17: } & (
18:   | { kind: "diagram"; contentId: string }
19:   | { kind: "container"; children: readonly GridBox[]; layout: { collisionPolicy: "push-right"; gap: number } }
20: );
21: 
22: export interface LineGridScene {
23:   contents: Readonly<Record<string, Diagram>>;
24:   root: GridBox;
25: }
26: 
27: export interface ResolvedGridBox {
28:   box: GridBox;
29:   /** Absolute scene coordinates. */
30:   bounds: GridBounds;
31:   contentId?: string;
32:   children: readonly ResolvedGridBox[];
33: }
34: 
35: // Bounds also limit accidental allocation when composing sparse text.
36: const MAX_EXTENT = 20000;
37: const MAX_CELLS = 4_000_000;
38: 
39: function integer(value: number, label: string): void {
40:   if (!Number.isInteger(value) || value < 0 || value > MAX_EXTENT) {
41:     throw new Error(`${label} must be an integer between 0 and ${MAX_EXTENT}`);
42:   }
43: }
44: 
45: export function measureContent(ascii: string): GridSize {
46:   if (/[^\x20-\x7e\n]/.test(ascii)) throw new Error("Grid content must be printable ASCII with LF newlines");
47:   const lines = ascii.split("\n");
48:   return { columns: Math.max(1, ...lines.map((line) => line.length)), rows: lines.length };
49: }
50: 
51: export function boxesOverlap(a: GridBounds, b: GridBounds, gap = 0): boolean {
52:   return a.row < b.row + b.rows && b.row < a.row + a.rows
53:     && a.column < b.column + b.columns + gap && b.column < a.column + a.columns + gap;
54: }
55: 
56: /** Measure without mutating input. Ancestor containment is not a collision. */
57: export function resolveScene(scene: LineGridScene): ResolvedGridBox {
58:   const ids = new Set<string>();
59:   function visit(box: GridBox, parent: GridPoint): ResolvedGridBox {
60:     if (ids.has(box.id)) throw new Error(`Duplicate GridBox id: ${box.id}`);
61:     ids.add(box.id);
62:     integer(box.position.column, "column");
63:     integer(box.position.row, "row");
64:     if (box.minimumSize) {
65:       integer(box.minimumSize.columns, "columns");
66:       integer(box.minimumSize.rows, "rows");
67:     }
68:     const origin = { column: parent.column + box.position.column, row: parent.row + box.position.row };
69:     integer(origin.column, "absolute column");
70:     integer(origin.row, "absolute row");
71:     if (box.kind === "container") integer(box.layout.gap, "gap");
72:     const contentId = box.collapsed ? box.collapsedContentId : box.kind === "diagram" ? box.contentId : undefined;
73:     if (box.collapsed && !contentId) throw new Error(`Collapsed box ${box.id} needs collapsed content`);
74:     let size: GridSize = { columns: 1, rows: 1 };
75:     if (contentId) {
76:       const content = scene.contents[contentId];
77:       if (!content) throw new Error(`Missing grid content: ${contentId}`);
78:       size = measureContent(content.content.ascii);
79:     }
80:     const children = box.kind === "container" && !box.collapsed
81:       ? box.children.map((child) => visit(child, origin)) : [];
82:     for (const child of children) {
83:       size.columns = Math.max(size.columns, child.bounds.column - origin.column + child.bounds.columns);
84:       size.rows = Math.max(size.rows, child.bounds.row - origin.row + child.bounds.rows);
85:     }
86:     // Reserved expanded space does not keep a collapsed box large.
87:     if (!box.collapsed && box.minimumSize) {
88:       size.columns = Math.max(size.columns, box.minimumSize.columns);
89:       size.rows = Math.max(size.rows, box.minimumSize.rows);
90:     }
91:     integer(origin.column + size.columns, "right edge");
92:     integer(origin.row + size.rows, "bottom edge");
93:     return { box, bounds: { ...origin, ...size }, contentId, children };
94:   }
95:   return visit(scene.root, { column: 0, row: 0 });
96: }
97: 
98: export function flattenGrid(root: ResolvedGridBox): ResolvedGridBox[] {
99:   return [root, ...root.children.flatMap(flattenGrid)];
100: }
101: 
102: export function findCollisions(scene: LineGridScene, parentId: string, bounds: GridBounds, excludeId?: string): string[] {
103:   const parent = flattenGrid(resolveScene(scene)).find((node) => node.box.id === parentId);
104:   if (!parent) throw new Error(`Unknown parent: ${parentId}`);
105:   return parent.children.filter((child) => child.box.id !== excludeId && boxesOverlap(child.bounds, bounds))
106:     .map((child) => child.box.id);
107: }
108: 
109: /** Immutable tree edit; use layoutScene afterward to commit the resulting positions. */
110: export function updateGridBox(scene: LineGridScene, id: string, update: (box: GridBox) => GridBox): LineGridScene {
111:   let found = false;
112:   function visit(box: GridBox): GridBox {
113:     if (box.id === id) { found = true; return update(box); }
114:     return box.kind === "container" ? { ...box, children: box.children.map(visit) } : box;
115:   }
116:   const root = visit(scene.root);
117:   if (!found) throw new Error(`Unknown GridBox: ${id}`);
118:   return { ...scene, root };
119: }
120: 
121: /**
122:  * Anchor the changed subtree at every ancestor. Settle other siblings in stable
123:  * spatial order, only moving right. Each settled box is an immutable obstacle,
124:  * so collision chains terminate without boxes repeatedly pushing each other.
125:  */
126: export function layoutScene(scene: LineGridScene, changedId: string): LineGridScene {
127:   function visit(box: GridBox): { box: GridBox; changed: boolean } {
128:     if (box.kind === "diagram") return { box, changed: box.id === changedId };
129:     const descendants = box.children.map(visit);
130:     let children = descendants.map((child) => child.box);
131:     const anchoredId = descendants.find((child) => child.changed)?.box.id;
132:     if (!box.collapsed) {
133:       const measure = (child: GridBox) => resolveScene({ ...scene, root: child }).bounds;
134:       const ordered = children.map((child, index) => ({ child, index })).sort((a, b) =>
135:         Number(b.child.id === anchoredId) - Number(a.child.id === anchoredId)
136:         || a.child.position.column - b.child.position.column
137:         || a.child.position.row - b.child.position.row || a.index - b.index);
138:       const settled: GridBounds[] = [];
139:       const replacements = new Map<string, GridBox>();
140:       for (const { child } of ordered) {
141:         const bounds = { ...measure(child) };
142:         let collisions = settled.filter((other) => boxesOverlap(bounds, other, box.layout.gap));
143:         while (collisions.length) {
144:           bounds.column = Math.max(...collisions.map((other) => other.column + other.columns + box.layout.gap));
145:           collisions = settled.filter((other) => boxesOverlap(bounds, other, box.layout.gap));
146:         }
147:         settled.push(bounds);
148:         replacements.set(child.id, { ...child, position: { column: bounds.column, row: bounds.row } });
149:       }
150:       children = children.map((child) => replacements.get(child.id)!);
151:     }
152:     return { box: { ...box, children }, changed: box.id === changedId || descendants.some((child) => child.changed) };
153:   }
154:   const result = visit(scene.root);
155:   if (!result.changed) throw new Error(`Unknown GridBox: ${changedId}`);
156:   const next = { ...scene, root: result.box };
157:   // Check all final bounds before publishing a transaction.
158:   composeScene(next);
159:   return next;
160: }
161: 
162: export function composeScene(scene: LineGridScene, renderContent?: (content: Diagram, box: GridBox) => string): string {
163:   const root = resolveScene(scene);
164:   const width = root.bounds.column + root.bounds.columns;
165:   const height = root.bounds.row + root.bounds.rows;
166:   if (width * height > MAX_CELLS) throw new Error("Grid exceeds the supported canvas size");
167:   const rows = Array.from({ length: height }, () => "");
168:   function paint(node: ResolvedGridBox): void {
169:     for (let i = 0; i < node.children.length; i++) {
170:       for (let j = i + 1; j < node.children.length; j++) {
171:         if (boxesOverlap(node.children[i].bounds, node.children[j].bounds)) {
172:           throw new Error(`GridBox collision: ${node.children[i].box.id} and ${node.children[j].box.id}`);
173:         }
174:       }
175:     }
176:     if (node.contentId) {
177:       const content = scene.contents[node.contentId];
178:       (renderContent ? renderContent(content, node.box) : content.content.ascii).split("\n").forEach((line, index) => {
179:         const row = node.bounds.row + index;
180:         const start = node.bounds.column;
181:         const existing = rows[row].padEnd(start, " ");
182:         rows[row] = existing.slice(0, start) + line + existing.slice(start + line.length);
183:       });
184:     }
185:     node.children.forEach(paint);
186:   }
187:   paint(root);
188:   return rows.join("\n");
189: }
190: 
191: export function hitTest(scene: LineGridScene, point: GridPoint): { boxId: string; contentId?: string; local: GridPoint } | null {
192:   function visit(node: ResolvedGridBox): ReturnType<typeof hitTest> {
193:     const b = node.bounds;
194:     if (point.column < b.column || point.column >= b.column + b.columns
195:       || point.row < b.row || point.row >= b.row + b.rows) return null;
196:     for (const child of node.children) {
197:       const hit = visit(child);
198:       if (hit) return hit;
199:     }
200:     return { boxId: node.box.id, contentId: node.contentId,
201:       local: { column: point.column - b.column, row: point.row - b.row } };
202:   }
203:   return visit(resolveScene(scene));
204: }
205: 
206: export function projectMapping(bounds: GridBounds, mapping: DiagramElementMapping): GridBounds {
207:   return { column: bounds.column + mapping.startColumn - 1, row: bounds.row + mapping.line - 1,
208:     columns: mapping.endColumn - mapping.startColumn + 1, rows: 1 };
209: }
